body {
    margin: 0px;
}

.bg-container {
    display: flex;
    align-items: center;
    flex-direction: column;
    background-color: #f0f4f8;
    color: #333;
    padding: 20px;
    height: 100vh;
    font-family: Roboto;
}

.heading {
    color: #3498db;
    margin-bottom: 32px;
}

.lang-cards {
    max-width: 1000px;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-around;
}

.card {
    background-color: #ffffff;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    padding: 25px;
    margin: 20px 10px 20px 10px;
    width: 400px;
}

.language-name {
    margin: 0 0 15px 0;
    color: #3498db;
    font-size: 24px;
    text-align: left;
    border-bottom: 2px solid #3498db;
    padding-bottom: 40px;
}

.feature-list {
    list-style-type: none;
    padding: 0;
    margin: 0;
}

.list-item {
    margin-bottom: 8px;
    padding-left: 20px;
}
